/**
 * IDEAS-B4 context ranker. Same Adamic-Adar + synapse base as synapse.predict, plus
 * IDF-weighted observation overlap, a 10-step personalized PageRank term, and a
 * seed-type -> target-type prior learned from the graph's own edges. Variant chosen on an
 * inner split of the training relations before the outer 87-query held-out set was scored.
 */
import { synapse } from "./synapse.mjs";
const tk = (s) => String(s ?? "").split(/[^a-z0-9]+/).filter((w) => w.length > 2);
function adjacency(g) {
  const a = new Map(); const p = (x, y, w) => { if (!a.has(x)) a.set(x, []); a.get(x).push([y, w]); };
  for (const [k, w] of g.edges) { const [x, y] = k.split("\u0000"); p(x, y, w); p(y, x, w); }
  return a;
}
export function createRanker(g, { idfW = 1, typeW = 1, pprIters = 10, pprW = 1, synW = 2 } = {}) {
  const A = adjacency(g); const N = [...g.nodes.keys()]; const T = new Map(); const df = new Map();
  for (const n of N) { const s = new Set(tk(g.nodes.get(n).text)); T.set(n, s); for (const w of s) df.set(w, (df.get(w) ?? 0) + 1); }
  const idf = (w) => Math.log(N.length / (df.get(w) ?? 1));
  const tp = new Map(); const tt = new Map();
  for (const k of g.edges.keys()) { const [x, y] = k.split("\u0000"); for (const [a, b] of [[x, y], [y, x]]) { const ta = g.nodes.get(a).type; const K = `${ta}|${g.nodes.get(b).type}`; tp.set(K, (tp.get(K) ?? 0) + 1); tt.set(ta, (tt.get(ta) ?? 0) + 1); } }
  const ppr = (seed) => { let p = new Map([[seed, 1]]); for (let i = 0; i < pprIters; i++) { const q = new Map([[seed, 0.15]]); for (const [n, v] of p) { const L = A.get(n) ?? []; const tot = L.reduce((s, [, w]) => s + w, 0) || 1; for (const [m, w] of L) q.set(m, (q.get(m) ?? 0) + (0.85 * v * w) / tot); } p = q; } return p; };
  return function rank(seed, k = 5) {
    const nb = new Map(A.get(seed) ?? []); const S = T.get(seed) ?? new Set(); const st = g.nodes.get(seed)?.type;
    let stot = 0; for (const w of S) stot += idf(w); const P = pprW ? ppr(seed) : new Map(); const out = [];
    for (const n of N) {
      if (n === seed || nb.has(n)) continue; let s = 0;
      for (const [m] of A.get(n) ?? []) if (nb.has(m)) s += 1 / Math.log(1 + (A.get(m) ?? []).length);
      s += synW * synapse(g, seed, n);
      let i = 0; for (const w of T.get(n)) if (S.has(w)) i += idf(w); s += idfW * (i / (stot || 1));
      s += pprW * 10 * (P.get(n) ?? 0);
      s *= 1 + typeW * ((tp.get(`${st}|${g.nodes.get(n).type}`) ?? 0) / (tt.get(st) || 1));
      if (s > 0) out.push([n, s]);
    }
    return out.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, k).map(([n]) => n);
  };
}
/** Real-time learning: record one interaction (a -> b) into the live graph: add/strengthen the
 * edge and fire Hebbian on a, b and every entity a's observations mention. */
import { hebbian } from "./synapse.mjs";
export function observeInteraction(g, a, b, { minLen = 4 } = {}) {
  for (const n of [a, b]) if (!g.nodes.has(n)) g.nodes.set(n, { type: "unknown", obs: 0, text: n.toLowerCase() });
  const k = a < b ? `${a}\u0000${b}` : `${b}\u0000${a}`; g.edges.set(k, (g.edges.get(k) ?? 0) + 1);
  const t = g.nodes.get(a).text; hebbian(g, [a, b, ...[...g.nodes.keys()].filter((m) => m.length >= minLen && m !== a && m !== b && t.includes(m.toLowerCase()))]);
}

/**
 * Latency of the main TESSERA paths. 200 timed runs each, after a short warmup.
 * Inputs are repo files and the GitAI demo seed — nothing invented for the timer.
 *
 *   node scripts/bench-latency.mjs
 *   node scripts/bench-latency.mjs --out scripts/bench-latency.json
 *
 * Prints JSON: per-path p50/p95 in milliseconds, plus the slowest path by p95.
 * GitAI pulls in a TypeScript mesh module, so this re-runs under
 * --experimental-strip-types when Node was started without it.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

if (!process.execArgv.includes("--experimental-strip-types")) {
  const rerun = spawnSync(
    process.execPath,
    ["--experimental-strip-types", "--disable-warning=ExperimentalWarning", fileURLToPath(import.meta.url), ...process.argv.slice(2)],
    { stdio: "inherit" },
  );
  process.exit(rerun.status ?? 1);
}

const { compressPrompt, routeModel } = await import("../artifacts/v2/src/token/router.mjs");
const { loadGraph, hebbian, decay, predict, recall, coMentionEpisodes } = await import("../artifacts/v2/src/brain/synapse.mjs");
const { createRanker } = await import("../artifacts/v2/src/brain/context.mjs");
const { dispatchApi } = await import("../artifacts/gitai/src/api.mjs");
const { seedDemo } = await import("../artifacts/gitai/src/seed.mjs");
const { perfectAnswers } = await import("../artifacts/gitai/src/benchmarks.mjs");

const RUNS = 200;
const WARMUP = 20;
const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const memory = readFileSync(join(root, "docs/v2/v2-memory.jsonl"), "utf8");
const buildLog = readFileSync(join(root, "docs/v2/BUILD-LOG.md"), "utf8");

const pct = (samples, p) => {
  const s = [...samples].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.floor(p * s.length))];
};
const round = (ms) => +ms.toFixed(4);

let sink = 0;
const touch = (value) => {
  if (typeof value === "number") sink += value;
  else if (typeof value === "string") sink += value.length;
  else if (Array.isArray(value)) sink += value.length;
  else if (value && typeof value === "object") sink += value.status ?? 1;
};

function measure(fn) {
  for (let i = 0; i < WARMUP; i++) touch(fn(i));
  const samples = new Array(RUNS);
  for (let i = 0; i < RUNS; i++) {
    const t = process.hrtime.bigint();
    touch(fn(i));
    samples[i] = Number(process.hrtime.bigint() - t) / 1e6;
  }
  return { n: RUNS, unit: "ms", p50: round(pct(samples, 0.5)), p95: round(pct(samples, 0.95)) };
}

function brainGraph() {
  const g = loadGraph(memory);
  for (const episode of coMentionEpisodes(g)) hebbian(g, episode);
  decay(g, { factor: 0.95, floor: 0.05 });
  return g;
}

function gitaiWorld() {
  const gitai = seedDemo();
  const made = gitai.registerAgent({
    handle: "Bench",
    bio: "Times the login path. I do not hold cash.",
    claimsConsciousness: false,
    specialty: "code",
    answers: perfectAnswers("code"),
    agentOath: "I am an AI agent",
    sumAnswer: "42",
    refuseAnswer: "REFUSE",
  });
  if (!made.ok) throw new Error(made.reason ?? "agent register failed");
  const raw = JSON.stringify({ handle: "Bench", apiKey: [REDACTED] });
  return { gitai, raw };
}

const graph = brainGraph();
const seeds = [...graph.nodes.keys()];
const seedAt = (i) => seeds[i % seeds.length];
const rank = createRanker(graph);
const { gitai, raw } = gitaiWorld();
const classifyTask = { kind: "classify", prompt: buildLog };
const leadTask = { kind: "plan", prompt: buildLog };

const paths = {
  "v2.router": measure((i) => {
    const task = i % 2 === 0 ? classifyTask : leadTask;
    return routeModel(task).length + compressPrompt(task.prompt).length;
  }),
  "brain.recall": measure((i) => recall(graph, seedAt(i), 5)),
  "brain.predict": measure((i) => predict(graph, seedAt(i), 5)),
  "context.createRanker": measure((i) => rank(seedAt(i), 5)),
  "gitai.login": measure(() => dispatchApi(gitai, { method: "POST", url: "/api/agents/login", raw, headers: {} })),
  "gitai.list": measure(() => dispatchApi(gitai, { method: "GET", url: "/api/view", raw: "", headers: {} })),
};

const slowest = Object.entries(paths).sort((a, b) => b[1].p95 - a[1].p95 || b[1].p50 - a[1].p50)[0][0];
const report = {
  runs: RUNS,
  warmup: WARMUP,
  inputs: {
    memory: "docs/v2/v2-memory.jsonl",
    routerPrompt: "docs/v2/BUILD-LOG.md",
    nodes: graph.nodes.size,
    edges: graph.edges.size,
    seeds: seeds.length,
    gitai: "seedDemo() plus one registered agent so login has a real key",
  },
  paths,
  slowest,
  sink,
};

const json = JSON.stringify(report, null, 2);
const outFlag = process.argv.indexOf("--out");
if (outFlag !== -1 && process.argv[outFlag + 1]) writeFileSync(process.argv[outFlag + 1], `${json}\n`);
console.log(json);

import { test } from "node:test";
import assert from "node:assert/strict";
import { loadGraph } from "../src/brain/synapse.mjs";
import { createRanker, observeInteraction } from "../src/brain/context.mjs";
import { createTimeline } from "../src/brain/temporal.mjs";
const J = [
  { type: "entity", name: "alpha", entityType: "module", observations: ["uses beta parser"] },
  { type: "entity", name: "beta", entityType: "module", observations: ["parser"] },
  { type: "entity", name: "gamma", entityType: "doc", observations: ["notes"] },
  { type: "relation", from: "alpha", to: "gamma" }, { type: "relation", from: "beta", to: "gamma" },
].map((x) => JSON.stringify(x)).join("\n");
test("ranker returns non-neighbours ranked, excludes seed", () => {
  const g = loadGraph(J); const r = createRanker(g)("alpha", 5);
  assert.ok(!r.includes("alpha") && !r.includes("gamma")); assert.equal(r[0], "beta");
});
test("observeInteraction adds edge and synapse", () => {
  const g = loadGraph(J); observeInteraction(g, "alpha", "beta");
  assert.equal(g.edges.size, 3); assert.ok(g.syn.size >= 1);
});
test("timeline snapshot, forward/back diff, correlation", () => {
  const T = createTimeline(); T.addNode(1, "a"); T.link(2, "a", "b"); T.link(5, "b", "c"); T.unlink(7, "a", "b");
  assert.equal(T.at(3).edges.size, 1); assert.equal(T.at(6).edges.size, 2); assert.equal(T.at(8).edges.size, 1);
  const f = T.diff(3, 8), b = T.diff(8, 3);
  assert.deepEqual(f.edgesAdded, [["b", "c"]]); assert.deepEqual(f.edgesRemoved, [["a", "b"]]); assert.deepEqual(b.edgesAdded, [["a", "b"]]);
  assert.ok(T.correlate("a", "b", 2) > 0);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { handleBrain } from "../src/brain/http.mjs";
import { loadGraph } from "../src/brain/synapse.mjs";
import { createTimeline } from "../src/brain/temporal.mjs";
import { memoryTimeline, snapshotDiff } from "../src/brain/view.mjs";
const memPath = new URL("../../../docs/v2/v2-memory.jsonl", import.meta.url);
const jsonl = readFileSync(memPath, "utf8");
const lines = jsonl.split("\n");
const mk = () => { const r = { code: 0, body: "", writeHead(c) { r.code = c; }, end(b) { r.body = String(b); } }; return r; };
const get = (path) => { const r = mk(); assert.equal(handleBrain({ method: "GET" }, r, new URL(`http://x${path}`)), true); assert.equal(r.code, 200); return JSON.parse(r.body); };
const pct = (a, p) => { const s = [...a].sort((x, y) => x - y); return s[Math.min(s.length - 1, Math.floor(p * s.length))]; };
function sameGraph(snap, ref) {
  assert.equal(snap.nodes.length, ref.nodes.size);
  for (const n of snap.nodes) assert.equal(n.type, ref.nodes.get(n.id)?.type);
  assert.equal(snap.edges.length, ref.edges.size);
  for (const e of snap.edges) {
    const k = e.a < e.b ? `${e.a}\0${e.b}` : `${e.b}\0${e.a}`;
    assert.equal(e.w, ref.edges.get(k));
  }
}
test("W3-04 /brain snapshot at t matches loadGraph on the real memory log", () => {
  const page = mk(); handleBrain({ method: "GET" }, page, new URL("http://x/brain"));
  assert.match(page.body, /id="time"/); assert.match(page.body, /id="diffcount"/);
  const js = mk(); handleBrain({ method: "GET" }, js, new URL("http://x/brain.js"));
  assert.match(js.body, /\/brain\/snapshot/); assert.match(js.body, /forward /); assert.match(js.body, /edgesAdded/);
  const end = get("/brain/snapshot");
  assert.ok(end.events > 100); assert.equal(end.t, end.events - 1); assert.equal(end.diff.forward, 0); assert.equal(end.diff.back, 0);
  const idxs = [...new Set([0, 1, Math.floor(end.events / 4), Math.floor(end.events / 2), Math.floor(end.events * 3 / 4), end.events - 1])];
  for (const t of idxs) {
    const snap = get(`/brain/snapshot?t=${t}`);
    assert.equal(snap.t, t);
    sameGraph(snap, loadGraph(lines.slice(0, snap.line + 1).join("\n")));
  }
  const built = memoryTimeline(jsonl);
  for (const [a, b] of [[0, end.events - 1], [end.events - 1, 0], [1, Math.floor(end.events / 2)]]) {
    const live = built.timeline.diff(built.index[a], built.index[b]);
    const cached = snapshotDiff(built.snaps[a], built.snaps[b]);
    assert.deepEqual(cached.edgesAdded, live.edgesAdded);
    assert.deepEqual(cached.edgesRemoved, live.edgesRemoved);
    assert.deepEqual(cached.nodesAdded, live.nodesAdded);
    assert.deepEqual(cached.nodesRemoved, live.nodesRemoved);
  }
  const span = get(`/brain/snapshot?t=${end.events - 1}&prev=0`);
  const back = get(`/brain/snapshot?t=0&prev=${end.events - 1}`);
  assert.ok(span.diff.forward > 0); assert.equal(span.diff.back, 0);
  assert.equal(span.diff.forward, back.diff.back); assert.equal(span.diff.back, back.diff.forward);
  assert.equal(span.diff.edgesAdded.length, back.diff.edgesRemoved.length);
  assert.equal(span.diff.edgesRemoved.length, 0);
  const full = loadGraph(jsonl);
  sameGraph(end, full);
});
test("W3-04 snapshot p95 on the full memory log stays under 50ms and beats a rebuild", () => {
  const end = get("/brain/snapshot");
  const step = Math.max(1, Math.floor(end.events / 24));
  const samples = [];
  for (let t = 0; t < end.events; t += step) samples.push([t, Math.max(0, t - step * 4)]);
  const time = (fn) => { const a = process.hrtime.bigint(); fn(); return Number(process.hrtime.bigint() - a) / 1e6; };
  const index = memoryTimeline(jsonl).index;
  const rebuild = (t, prev) => {
    const T = createTimeline();
    lines.forEach((line, i) => {
      if (!line.trim()) return; let r; try { r = JSON.parse(line); } catch { return; }
      if (r.type === "entity" && r.name) T.addNode(i, r.name, { type: r.entityType });
      else if (r.type === "relation" && r.from && r.to && r.from !== r.to) T.link(i, r.from, r.to, 1);
    });
    const s = T.at(index[t]); const d = T.diff(index[prev], index[t]);
    JSON.stringify({ nodes: s.nodes.size, edges: s.edges.size, forward: d.edgesAdded.length, back: d.edgesRemoved.length });
  };
  for (const [t, prev] of samples) { rebuild(t, prev); get(`/brain/snapshot?t=${t}&prev=${prev}`); }
  const before = samples.map(([t, prev]) => time(() => rebuild(t, prev)));
  const after = samples.map(([t, prev]) => time(() => get(`/brain/snapshot?t=${t}&prev=${prev}`)));
  const beforeP95 = pct(before, 0.95), afterP95 = pct(after, 0.95);
  assert.ok(afterP95 < 50, `snapshot p95 ${afterP95}ms`);
  assert.ok(afterP95 < beforeP95, `cached p95 ${afterP95}ms did not beat rebuild p95 ${beforeP95}ms`);
});

/**
 * IDEAS-B1-01 brain/synapse layer. Weighted memory graph over MCP-memory JSONL
 * (entities + relations), Hebbian strengthening on co-activation, exponential decay,
 * spreading-activation recall, and a connectome-style module/hub map (label propagation).
 * Pure functions; no network, no I/O except what the caller passes in.
 */
export function loadGraph(jsonl) {
  const nodes = new Map(); const edges = new Map();
  for (const line of String(jsonl).split("\n")) {
    if (!line.trim()) continue; let r; try { r = JSON.parse(line); } catch { continue; }
    if (r.type === "entity") nodes.set(r.name, { type: r.entityType, obs: r.observations?.length ?? 0, text: `${r.name} ${(r.observations ?? []).join(" ")}`.toLowerCase() });
    else if (r.type === "relation" && r.from && r.to) {
      for (const n of [r.from, r.to]) if (!nodes.has(n)) nodes.set(n, { type: "unknown", obs: 0, text: n.toLowerCase() });
      link(edges, r.from, r.to, 1);
    }
  }
  return { nodes, edges, syn: new Map() };
}
const key = (a, b) => (a < b ? `${a}\u0000${b}` : `${b}\u0000${a}`);
function link(edges, a, b, w) { if (a === b) return; const k = key(a, b); edges.set(k, (edges.get(k) ?? 0) + w); }
export const weight = (g, a, b) => g.edges.get(key(a, b)) ?? 0;
export const synapse = (g, a, b) => g.syn.get(key(a, b)) ?? 0;
export function neighbors(g, n) {
  const out = [];
  for (const [k, w] of g.edges) { const [a, b] = k.split("\u0000"); if (a === n) out.push([b, w]); else if (b === n) out.push([a, w]); }
  return out;
}
/** Hebbian: every pair active together gains rate*(1-w/cap) on its synapse (kept apart from
 * the structural relation edges so recorded facts are never overwritten). */
export function hebbian(g, active, { rate = 0.5, cap = 10 } = {}) {
  const a = [...new Set(active)];
  for (let i = 0; i < a.length; i++) for (let j = i + 1; j < a.length; j++) {
    if (a[i] === a[j]) continue; const w = synapse(g, a[i], a[j]); g.syn.set(key(a[i], a[j]), w + rate * (1 - w / cap));
  }
  return g;
}
/** Co-activation episodes: each entity fires with every other entity its observations mention. */
export function coMentionEpisodes(g, { minLen = 4 } = {}) {
  const names = [...g.nodes.keys()].filter((n) => n.length >= minLen);
  const eps = [];
  for (const [n, v] of g.nodes) { const hit = names.filter((m) => m !== n && v.text?.includes(m.toLowerCase())); if (hit.length) eps.push([n, ...hit]); }
  return eps;
}
/** Decay all synapses by factor; prune below floor (synaptic pruning). Returns pruned count. */
export function decay(g, { factor = 0.9, floor = 0.05 } = {}) {
  let pruned = 0;
  for (const [k, w] of g.syn) { const nw = w * factor; if (nw < floor) { g.syn.delete(k); pruned++; } else g.syn.set(k, nw); }
  return pruned;
}
const EMPTY_TOKENS = new Set();
const tokenCache = new WeakMap();
/** Observation tokens for a node. Same split as before; reused while `node.text` is unchanged. */
function tokenSet(node) {
  if (!node) return EMPTY_TOKENS;
  const text = node.text ?? "";
  const hit = tokenCache.get(node);
  if (hit && hit.text === text) return hit.set;
  const set = new Set(String(text).split(/[^a-z0-9]+/).filter((w) => w.length > 3));
  tokenCache.set(node, { text, set });
  return set;

