node --experimental-strip-types --disable-warning=ExperimentalWarning -e '
import { readFileSync } from "node:fs";
import { loadGraph, hebbian, decay, coMentionEpisodes } from "./artifacts/v2/src/brain/synapse.mjs";
import { createRanker } from "./artifacts/v2/src/brain/context.mjs";
const memory = readFileSync("docs/v2/v2-memory.jsonl", "utf8");
const t0 = process.hrtime.bigint();
